-- Window SUM, AVG, MIN and MAX over TINYINT, SMALLINT and INTEGER columns
-- holding their types' extremes and NULLs, over running, bounded and whole
-- frames.
SELECT id, sum(i8) OVER (ORDER BY id ASC NULLS LAST) AS s8, avg(i8) OVER (ORDER BY id ASC NULLS LAST ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS a8, min(i8) OVER () AS mn8, sum(i16) OVER (ORDER BY id ASC NULLS LAST ROWS BETWEEN 2 PRECEDING AND 2 FOLLOWING) AS s16, avg(i16) OVER (ORDER BY id ASC NULLS LAST) AS a16, max(i16) OVER (ORDER BY id ASC NULLS LAST ROWS BETWEEN 1 PRECEDING AND CURRENT ROW) AS mx16, sum(i32) OVER (ORDER BY id ASC NULLS LAST) AS s32, avg(i32) OVER () AS a32, min(i32) OVER (ORDER BY id ASC NULLS LAST ROWS BETWEEN 4 PRECEDING AND CURRENT ROW) AS mn32, max(i32) OVER (ORDER BY id ASC NULLS LAST) AS mx32 FROM types ORDER BY id ASC NULLS LAST
